:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-wash: #fafafa;
  --color-pebble-card: #f5f5f5;
  --color-pewter-well: #efeff1;
  --color-dusk-sky: #7b9cc4;
  --color-mist-sky: #c8dff0;
  --color-jet-ink: #070709;
  --color-carbon-heading: #151515;
  --color-slate-body: #60606c;
  --color-steel-caption: #868c98;
  --color-dove-hint: #bec2ca;
  --color-glacier-signal: #2597d0;
  --color-frosted-tint: #c0eaff;

  /* Typography — Font Families */
  --font-open-runde: "Open Runde", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-the-doctor-freeversion: "The Doctor FreeVersion", "Homemade Apple", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.45;
  --tracking-caption: -0.08px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: -0.14px;
  --text-body: 16px;
  --leading-body: 1.4;
  --tracking-body: -0.16px;
  --text-body-lg: 17px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: -0.17px;
  --text-subheading: 18px;
  --leading-subheading: 1.4;
  --tracking-subheading: -0.18px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.4;
  --tracking-heading-sm: -0.2px;
  --text-heading: 28px;
  --leading-heading: 1.2;
  --tracking-heading: -0.84px;
  --text-heading-lg: 44px;
  --leading-heading-lg: 1.1;
  --tracking-heading-lg: -1.76px;
  --text-display: 80px;
  --leading-display: 0.9;
  --tracking-display: -3.2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-40: 40px;
  --spacing-52: 52px;
  --spacing-80: 80px;
  --spacing-100: 100px;
  --spacing-120: 120px;

  /* Layout */
  --layout-max-width: 1400px;
  --layout-section-gap: 100px;
  --layout-card-padding: 40px;
  --layout-element-gap: 10px;

  /* Border Radius */
  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 18px;
  --radius-xl: 24px;
  --radius-2xl: 32px;
  --radius-3xl: 40px;
  --radius-3xl-2: 48px;
  --radius-full: 100px;

  /* Named Radii */
  --radius-cards: 48px;
  --radius-sections: 40px;
  --radius-small-cards: 32px;
  --radius-inner-tiles: 18px;
  --radius-inputs: 18px;
  --radius-images: 18px;
  --radius-small-elements: 10px;
  --radius-buttons: 100px;
  --radius-pills: 100px;
  --radius-badges: 100px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: rgba(228, 229, 231, 0.24) 0px 1px 2px 0px;
  --shadow-sm: rgba(23, 107, 197, 0.08) 0px 1px 1px 0px, rgba(23, 107, 197, 0.07) 0px 3px 3px 0px;
  --shadow-md: rgba(22, 106, 196, 0.01) 0px 0.42px 0.42px 0px, rgba(22, 106, 196, 0.04) 0px 1.6px 1.6px 0px, rgba(22, 106, 196, 0.17) 0px 7px 7px 0px;
  --shadow-md-2: rgba(22, 107, 197, 0) 0px 0.42px 0.42px 0px, rgba(22, 107, 197, 0.01) 0px 1.6px 1.6px 0px, rgba(22, 107, 197, 0.05) 0px 7px 7px 0px;
  --shadow-md-3: rgba(9, 62, 119, 0.01) 0px 0.42px 0.42px 0px, rgba(9, 62, 119, 0.02) 0px 1.6px 1.6px 0px, rgba(9, 62, 119, 0.1) 0px 7px 7px 0px;
  --shadow-lg: rgba(36, 36, 40, 0.1) 0px 1px 2px 0px, rgba(36, 36, 40, 0.09) 0px 3px 3px 0px, rgba(36, 36, 40, 0.05) 0px 6px 4px 0px, rgba(36, 36, 40, 0.01) 0px 11px 4px 0px, rgba(36, 36, 40, 0) 0px 17px 5px 0px;
  --shadow-xl: rgba(16, 55, 132, 0) 0px 17px 37px 0px, rgba(16, 55, 132, 0) 0px 67px 67px 0px, rgba(16, 55, 132, 0) 0px 150px 90px 0px, rgba(16, 55, 132, 0) 0px 266px 106px 0px, rgba(16, 55, 132, 0) 0px 416px 116px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-wash: #fafafa;
  --surface-pebble-card: #f5f5f5;
  --surface-dusk-sky: #7b9cc4;
  --surface-jet-ink: #070709;
}

